'use strict';
const express=require('express'),crypto=require('crypto'),fs=require('fs'),path=require('path'),{db}=require('./db'),{encrypt,decrypt}=require('./crypto'),{DATA_DIR}=require('./paths');
const router=express.Router(),pending=new Map(),sendLocks=new Set();
db.exec('CREATE TABLE IF NOT EXISTS monday_google_private(key TEXT PRIMARY KEY,value TEXT NOT NULL);CREATE TABLE IF NOT EXISTS monday_google_drafts(id TEXT PRIMARY KEY,summary TEXT NOT NULL,sent_id TEXT,created_at TEXT NOT NULL)');
const get=k=>{const r=db.prepare('SELECT value FROM monday_google_private WHERE key=?').get(k);return r?JSON.parse(decrypt(r.value)):null},set=(k,v)=>db.prepare('INSERT OR REPLACE INTO monday_google_private(key,value) VALUES(?,?)').run(k,encrypt(JSON.stringify(v)));
const wrap=fn=>async(req,res)=>{try{await fn(req,res)}catch(e){res.status(e.status||400).json({error:e.message})}};
router.use((req,res,next)=>{const origin=req.get('origin');if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress)||(origin&&!/^http:\/\/(localhost|127\.0\.0\.1):(?:3001|3099)$/.test(origin)))return res.status(403).json({error:'Chỉ kết nối từ app trên máy này.'});res.set('Cache-Control','no-store');next()});
async function request(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(30000)}),data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error?.message||data.error_description||'Google không chấp nhận yêu cầu ('+r.status+'). Kiểm tra quyền truy cập hoặc đăng nhập lại.');return data}
async function token(){let t=get('token');if(!t)throw Error('Chưa kết nối Gmail. Mở Kết nối Google và đăng nhập.');if(t.expires_at>Date.now()+60000)return t.access_token;const c=get('client');if(!c||!t.refresh_token)throw Error('Cần kết nối Gmail lại.');const n=await request('https://oauth2.googleapis.com/token',{method:'POST',body:new URLSearchParams({client_id:c.client_id,client_secret:c.client_secret||'',refresh_token:t.refresh_token,grant_type:'refresh_token'})});t={...t,...n,expires_at:Date.now()+n.expires_in*1000};set('token',t);return t.access_token}
async function gmail(route,body){return request('https://gmail.googleapis.com/gmail/v1/users/me'+route,{headers:{Authorization:'Bearer '+await token(),...(body?{'Content-Type':'application/json'}:{})},...(body?{method:'POST',body:JSON.stringify(body)}:{})})}
const header=(p,name)=>p?.headers?.find(h=>h.name.toLowerCase()===name.toLowerCase())?.value||'';
function plain(p){if(p?.mimeType==='text/plain'&&p.body?.data)return Buffer.from(p.body.data,'base64url').toString('utf8');return(p?.parts||[]).map(plain).filter(Boolean).join('\n')}
router.get('/status',wrap(async(req,res)=>res.json({configured:!!get('client'),connected:!!get('token'),email:get('profile')?.emailAddress||null,flowMode:'browser-handoff'})));
router.post('/configure',wrap(async(req,res)=>{const c=req.body?.credentials?.installed;if(!c?.client_id?.endsWith('.apps.googleusercontent.com')||typeof c.client_secret!=='string')throw Error('Chọn file OAuth Client JSON loại Desktop app từ Google Cloud.');set('client',{client_id:c.client_id,client_secret:c.client_secret});db.prepare("DELETE FROM monday_google_private WHERE key IN ('token','profile')").run();res.json({success:true})}));
router.post('/authorize',wrap(async(req,res)=>{const c=get('client');if(!c)throw Error('Thêm OAuth Client JSON trước khi đăng nhập.');for(const [k,v]of pending)if(v.expires<Date.now())pending.delete(k);const state=crypto.randomBytes(24).toString('hex'),verifier=crypto.randomBytes(48).toString('base64url'),redirect='http://127.0.0.1:3001/api/workflow-google/callback';pending.set(state,{verifier,redirect,expires:Date.now()+600000});const u=new URL('https://accounts.google.com/o/oauth2/v2/auth');for(const[k,v]of Object.entries({client_id:c.client_id,redirect_uri:redirect,response_type:'code',scope:'https://www.googleapis.com/auth/gmail.readonly https://www.googleapis.com/auth/gmail.compose',state,code_challenge:crypto.createHash('sha256').update(verifier).digest('base64url'),code_challenge_method:'S256',access_type:'offline',prompt:'consent'}))u.searchParams.set(k,v);res.json({url:u.href})}));
router.get('/callback',async(req,res)=>{const state=String(req.query.state||''),p=pending.get(state);pending.delete(state);try{if(!p||p.expires<Date.now())throw Error('Lượt đăng nhập không hợp lệ hoặc hết hạn.');if(req.query.error)throw Error('Bạn chưa cấp quyền Gmail.');const c=get('client'),t=await request('https://oauth2.googleapis.com/token',{method:'POST',body:new URLSearchParams({client_id:c.client_id,client_secret:c.client_secret,code:String(req.query.code||''),code_verifier:p.verifier,redirect_uri:p.redirect,grant_type:'authorization_code'})});set('token',{...t,expires_at:Date.now()+t.expires_in*1000});set('profile',await gmail('/profile'));res.type('html').send('<meta charset="utf-8"><title>MUSE · Google</title><h2>Đã kết nối Gmail</h2><p>Bạn có thể đóng trang này và quay lại MUSE.</p>')}catch{res.status(400).type('html').send('<meta charset="utf-8"><h2>Chưa kết nối được Gmail</h2><p>Quay lại MUSE, kiểm tra OAuth Client, Gmail API và tài khoản thử nghiệm rồi kết nối lại.</p>')}});
router.post('/disconnect',wrap(async(req,res)=>{const t=get('token');if(t)await fetch('https://oauth2.googleapis.com/revoke',{method:'POST',body:new URLSearchParams({token:t.refresh_token||t.access_token}),signal:AbortSignal.timeout(10000)}).catch(()=>{});db.prepare("DELETE FROM monday_google_private WHERE key IN ('token','profile')").run();pending.clear();res.json({success:true})}));
router.get('/messages',wrap(async(req,res)=>{const result=await gmail('/messages?maxResults=10&q='+encodeURIComponent(String(req.query.q||'in:inbox').slice(0,500)));const messages=await Promise.all((result.messages||[]).map(async m=>{const d=await gmail('/messages/'+encodeURIComponent(m.id)+'?format=metadata&metadataHeaders=Subject&metadataHeaders=From');return{id:d.id,subject:header(d.payload,'Subject'),from:header(d.payload,'From'),snippet:d.snippet}}));res.json({messages})}));
router.get('/messages/:id',wrap(async(req,res)=>{const d=await gmail('/messages/'+encodeURIComponent(req.params.id)+'?format=full');res.json({id:d.id,subject:header(d.payload,'Subject'),from:header(d.payload,'From'),text:(plain(d.payload)||d.snippet||'').slice(0,20000)})}));
function mimeMessage({to,subject,text,attachments=[]}){if(typeof to!=='string'||!to.split(',').every(v=>/^[^\s@,<>]+@[^\s@,<>]+\.[^\s@,<>]+$/.test(v.trim()))||/[\r\n]/.test(to))throw Error('Nhập địa chỉ email hợp lệ.');if(typeof subject!=='string'||!subject.trim()||subject.length>200||/[\r\n]/.test(subject))throw Error('Tiêu đề không hợp lệ.');if(typeof text!=='string'||text.length>50000)throw Error('Nội dung email tối đa 50.000 ký tự.');if(!Array.isArray(attachments)||attachments.length>5)throw Error('Tối đa 5 file đính kèm.');const boundary='muse_'+crypto.randomBytes(12).toString('hex'),parts=[`To: ${to}`,`Subject: =?UTF-8?B?${Buffer.from(subject).toString('base64')}?=`,'MIME-Version: 1.0',`Content-Type: multipart/mixed; boundary="${boundary}"`,'',`--${boundary}`,'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','',Buffer.from(text).toString('base64')];let total=0;for(const url of attachments){if(typeof url!=='string'||!/^\/(uploads|videos)\/[\w.-]+$/.test(url))throw Error('Chỉ đính kèm kết quả trên máy.');const file=path.join(DATA_DIR,url.slice(1)),real=fs.realpathSync(file),dir=fs.realpathSync(path.join(DATA_DIR,url.split('/')[1]));if(path.dirname(real)!==dir)throw Error('Đường dẫn tệp không hợp lệ.');const stat=fs.statSync(real);total+=stat.size;if(total>12*1024*1024)throw Error('Tổng file vượt 12 MB. Hãy xuất video rồi chia sẻ theo cách khác.');const name=path.basename(file);parts.push(`--${boundary}`,'Content-Type: application/octet-stream',`Content-Disposition: attachment; filename="${name}"`,'Content-Transfer-Encoding: base64','',fs.readFileSync(real).toString('base64').match(/.{1,76}/g)?.join('\r\n')||'')}parts.push(`--${boundary}--`);return Buffer.from(parts.join('\r\n')).toString('base64url')}
router.post('/drafts',wrap(async(req,res)=>{const raw=mimeMessage(req.body),d=await gmail('/drafts',{message:{raw}});const summary={to:req.body.to,subject:req.body.subject,text:req.body.text,attachments:req.body.attachments||[]};db.prepare('INSERT INTO monday_google_drafts(id,summary,created_at) VALUES(?,?,?)').run(d.id,JSON.stringify(summary),new Date().toISOString());res.json({id:d.id,summary})}));
router.post('/drafts/:id/send',wrap(async(req,res)=>{const id=req.params.id,row=db.prepare('SELECT * FROM monday_google_drafts WHERE id=?').get(id);if(!row)throw Error('Chỉ gửi bản nháp được tạo bởi MUSE.');if(req.body?.confirmed!==true)throw Error('Cần xem và xác nhận trước khi gửi.');if(row.sent_id)return res.json({id:row.sent_id,alreadySent:true});if(sendLocks.has(id))throw Error('Email đang gửi; không bấm lại.');sendLocks.add(id);try{const d=await gmail('/drafts/send',{id});db.prepare('UPDATE monday_google_drafts SET sent_id=? WHERE id=?').run(d.id,id);res.json({id:d.id})}finally{sendLocks.delete(id)}}));
module.exports={router,mimeMessage,plain};
